    u16(b,1); b.insert(b.end(),{1,0}); u16(b,0); b.push_back(1); b.insert(b.end(),{247,197,18,59});
    u16(b,animations*framesPerAnimation); for (int i=0;i<animations*framesPerAnimation;++i) b.insert(b.end(),{0,2,0,0,0});
    u16(b,animations); for (int i=0;i<animations;++i) { b.push_back(static_cast<std::uint8_t>(framesPerAnimation));b.push_back(0);u16(b,i*framesPerAnimation); }
